import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ContainerSwapper {

    static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }

    static class ElementCount {
        private int e;

        ElementCount(int e) {
            this.e = e;
        }

        int getE() {
            return e;
        }

        void setE(int e) {
            this.e = e;
        }
    }

    static class Container {
        private final ReentrantLock lock = new ReentrantLock();
        private final ElementCount elementCount;

        Container(int initialElements) {
            this.elementCount = new ElementCount(initialElements);
        }

        ReentrantLock getLock() {
            return lock;
        }

        ElementCount getElementCount() {
            return elementCount;
        }
    }

    private static final Random RANDOM = new Random();
    private static final long FIXED_DELAY_MS = 50L;
    private static final long RANDOM_DELAY_BOUND_MS = 50L;

    private static long fixedDelay() {
        return FIXED_DELAY_MS;
    }

    private static long randomDelay() {
        return RANDOM.nextInt((int) RANDOM_DELAY_BOUND_MS);
    }

    public static boolean swap(Container origin, Container target, int count, long timeout, TimeUnit unit)
            throws InsufficientElementsException, InterruptedException {
        long stopTime = System.nanoTime() + unit.toNanos(timeout);
        while (true) {
            if (System.nanoTime() >= stopTime) {
                return false;
            }
            if (origin.getLock().tryLock()) {
                try {
                    if (target.getLock().tryLock()) {
                        try {
                            // Every access to the shared ElementCount field is made while
                            // holding both container locks, so there is a well-defined
                            // happens-before edge between threads touching "e".
                            if (origin.getElementCount().getE() < count) {
                                throw new InsufficientElementsException("Origin container does not have enough elements");
                            }
                            origin.getElementCount().setE(origin.getElementCount().getE() - count);
                            target.getElementCount().setE(target.getElementCount().getE() + count);
                            return true;
                        } finally {
                            target.getLock().unlock();
                        }
                    }
                } finally {
                    origin.getLock().unlock();
                }
            }
            long remaining = stopTime - System.nanoTime();
            if (remaining <= 0) {
                return false;
            }
            long sleepMs = Math.min(fixedDelay() + randomDelay(), TimeUnit.NANOSECONDS.toMillis(remaining));
            if (sleepMs > 0) {
                Thread.sleep(sleepMs);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Container containerA = new Container(10);
        Container containerB = new Container(5);

        Runnable task1 = () -> {
            try {
                boolean swapped = swap(containerA, containerB, 3, 2, TimeUnit.SECONDS);
                System.out.println("Task1 swap result: " + swapped);
            } catch (InsufficientElementsException e) {
                System.out.println("Task1 failed: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable task2 = () -> {
            try {
                boolean swapped = swap(containerB, containerA, 2, 2, TimeUnit.SECONDS);
                System.out.println("Task2 swap result: " + swapped);
            } catch (InsufficientElementsException e) {
                System.out.println("Task2 failed: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Thread t1 = new Thread(task1);
        Thread t2 = new Thread(task2);
        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Container A elements: " + containerA.getElementCount().getE());
        System.out.println("Container B elements: " + containerB.getElementCount().getE());
    }
}

